import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

abstract class Node {
    protected final String name;
    protected Directory parent;
    protected final Instant createdAt = Instant.now();

    protected Node(String name, Directory parent) {
        this.name = name;
        this.parent = parent;
    }

    public abstract long getSize();
    public abstract boolean isDirectory();

    public String getName()        { return name; }
    public Directory getParent()   { return parent; }
    public void setParent(Directory p) { this.parent = p; }

    // Build full path by walking up to root
    public String getPath() {
        if (parent == null) return "/";  // root
        StringBuilder sb = new StringBuilder();
        Node n = this;
        while (n.parent != null) {
            sb.insert(0, "/" + n.name);
            n = n.parent;
        }
        return sb.toString();
    }
}

class File extends Node {
    private final StringBuilder content = new StringBuilder();

    public File(String name, Directory parent) {
        super(name, parent);
    }

    public synchronized String read() {
        return content.toString();
    }

    public synchronized void write(String newContent) {
        content.setLength(0);
        content.append(newContent);
    }

    public synchronized void append(String moreContent) {
        content.append(moreContent);
    }

    @Override
    public synchronized long getSize() {
        return content.length();
    }

    @Override
    public boolean isDirectory() { return false; }
}

class Directory extends Node {
    // ConcurrentHashMap → safe iteration during concurrent mutation
    private final ConcurrentHashMap<String, Node> children = new ConcurrentHashMap<>();

    public Directory(String name, Directory parent) {
        super(name, parent);
    }

    public void addChild(Node node) {
        children.put(node.getName(), node);
    }

    public Node removeChild(String name) {
        return children.remove(name);
    }

    public Node getChild(String name) {
        return children.get(name);
    }

    public List<String> listChildren() {
        return new ArrayList<>(children.keySet());
    }

    public boolean isEmpty() {
        return children.isEmpty();
    }

    public Collection<Node> getAllChildren() {
        return children.values();
    }

    @Override
    public long getSize() {
        // Recursive sum of all descendant sizes
        return children.values().stream().mapToLong(Node::getSize).sum();
    }

    @Override
    public boolean isDirectory() { return true; }
}

import java.util.concurrent.locks.ReentrantReadWriteLock;

class FileSystem {
    private final Directory root = new Directory("", null);
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    // ── Path parsing helper ──
    private String[] splitPath(String path) {
        if (path == null || path.isEmpty() || !path.startsWith("/"))
            throw new InvalidPathException("Path must start with /: " + path);
        if (path.equals("/")) return new String[0];
        return Arrays.stream(path.substring(1).split("/"))
            .filter(s -> !s.isEmpty())
            .toArray(String[]::new);
    }

    // Walk tree to find a node — read-only
    private Node resolve(String path) {
        String[] parts = splitPath(path);
        Node current = root;
        for (String part : parts) {
            if (!(current instanceof Directory dir))
                throw new NotADirectoryException("Not a directory: " + part);
            Node next = dir.getChild(part);
            if (next == null)
                throw new PathNotFoundException("Path not found: " + path);
            current = next;
        }
        return current;
    }

    // ── mkdir ──────────────────────────
    public void mkdir(String path) {
        lock.writeLock().lock();
        try {
            String[] parts = splitPath(path);
            if (parts.length == 0)
                throw new PathAlreadyExistsException("/");

            String[] parentParts = Arrays.copyOf(parts, parts.length - 1);
            String name = parts[parts.length - 1];
            String parentPath = "/" + String.join("/", parentParts);

            Node parentNode = (parentParts.length == 0) ? root : resolve(parentPath);
            if (!(parentNode instanceof Directory parent))
                throw new NotADirectoryException(parentPath);
            if (parent.getChild(name) != null)
                throw new PathAlreadyExistsException(path);

            parent.addChild(new Directory(name, parent));
        } finally {
            lock.writeLock().unlock();
        }
    }

    // ── mkdirAll (mkdir -p) ─────────────
    public void mkdirAll(String path) {
        lock.writeLock().lock();
        try {
            String[] parts = splitPath(path);
            Directory current = root;
            for (String part : parts) {
                Node child = current.getChild(part);
                if (child == null) {
                    Directory dir = new Directory(part, current);
                    current.addChild(dir);
                    current = dir;
                } else if (child instanceof Directory d) {
                    current = d;
                } else {
                    throw new NotADirectoryException(
                        "Path contains a file: " + part);
                }
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    // ── ls ──────────────────────────────
    public List<String> ls(String path) {
        lock.readLock().lock();
        try {
            Node node = resolve(path);
            if (!(node instanceof Directory dir))
                throw new NotADirectoryException(path);
            List<String> children = dir.listChildren();
            Collections.sort(children);
            return children;
        } finally {
            lock.readLock().unlock();
        }
    }

    // ── cat ─────────────────────────────
    public String cat(String path) {
        lock.readLock().lock();
        try {
            Node node = resolve(path);
            if (!(node instanceof File file))
                throw new NotAFileException(path);
            return file.read();
        } finally {
            lock.readLock().unlock();
        }
    }

    // ── write (overwrite or create) ─────
    public void write(String path, String content) {
        lock.writeLock().lock();
        try {
            String[] parts = splitPath(path);
            if (parts.length == 0)
                throw new InvalidPathException("Cannot write to root");

            String[] parentParts = Arrays.copyOf(parts, parts.length - 1);
            String name = parts[parts.length - 1];
            String parentPath = "/" + String.join("/", parentParts);

            Node parentNode = (parentParts.length == 0) ? root : resolve(parentPath);
            if (!(parentNode instanceof Directory parent))
                throw new NotADirectoryException(parentPath);

            Node existing = parent.getChild(name);
            if (existing == null) {
                File file = new File(name, parent);
                file.write(content);
                parent.addChild(file);
            } else if (existing instanceof File file) {
                file.write(content);
            } else {
                throw new NotAFileException(path);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void append(String path, String content) {
        lock.writeLock().lock();
        try {
            Node node = resolve(path);
            if (!(node instanceof File file))
                throw new NotAFileException(path);
            file.append(content);
        } finally {
            lock.writeLock().unlock();
        }
    }

    // ── rm ──────────────────────────────
    public void rm(String path, boolean recursive) {
        lock.writeLock().lock();
        try {
            Node node = resolve(path);
            if (node == root)
                throw new InvalidPathException("Cannot delete root");

            if (node instanceof Directory dir && !dir.isEmpty() && !recursive)
                throw new DirectoryNotEmptyException(path);

            // Detach from parent — orphans the entire subtree
            node.getParent().removeChild(node.getName());
        } finally {
            lock.writeLock().unlock();
        }
    }

    // ── mv (rename or move) ──────────────
    public void mv(String from, String to) {
        lock.writeLock().lock();
        try {
            Node sourceNode = resolve(from);
            if (sourceNode == root)
                throw new InvalidPathException("Cannot move root");

            String[] toParts = splitPath(to);
            if (toParts.length == 0)
                throw new PathAlreadyExistsException("/");

            String[] toParentParts = Arrays.copyOf(toParts, toParts.length - 1);
            String newName = toParts[toParts.length - 1];
            String toParentPath = "/" + String.join("/", toParentParts);

            Node targetParentNode = (toParentParts.length == 0) ? root : resolve(toParentPath);
            if (!(targetParentNode instanceof Directory targetParent))
                throw new NotADirectoryException(toParentPath);
            if (targetParent.getChild(newName) != null)
                throw new PathAlreadyExistsException(to);

            // Cycle check: cannot move a directory into itself or a descendant
            if (sourceNode instanceof Directory) {
                Node walker = targetParent;
                while (walker != null) {
                    if (walker == sourceNode)
                        throw new InvalidPathException(
                            "Cannot move directory into itself or a descendant");
                    walker = walker.getParent();
                }
            }

            // Detach from old parent, attach to new
            sourceNode.getParent().removeChild(sourceNode.getName());
            // Rename — needs reflection or a setName method (omitted setter for brevity)
            // For correctness, recreate with new name:
            Node renamed = (sourceNode instanceof File f)
                ? cloneFile(f, newName, targetParent)
                : cloneDir((Directory) sourceNode, newName, targetParent);
            targetParent.addChild(renamed);
        } finally {
            lock.writeLock().unlock();
        }
    }

    // ── find (recursive search) ──────────
    public List<String> find(String rootPath, String pattern) {
        lock.readLock().lock();
        try {
            Node startNode = resolve(rootPath);
            List<String> results = new ArrayList<>();
            findRecursive(startNode, pattern, results);
            return results;
        } finally {
            lock.readLock().unlock();
        }
    }

    private void findRecursive(Node node, String pattern, List<String> results) {
        if (node.getName().contains(pattern)) {
            results.add(node.getPath());
        }
        if (node instanceof Directory dir) {
            for (Node child : dir.getAllChildren()) {
                findRecursive(child, pattern, results);
            }
        }
    }

    // Helpers (simplified — production would handle deep clones differently)
    private File cloneFile(File f, String newName, Directory parent) {
        File copy = new File(newName, parent);
        copy.write(f.read());
        return copy;
    }

    private Directory cloneDir(Directory d, String newName, Directory parent) {
        Directory copy = new Directory(newName, parent);
        for (Node child : d.getAllChildren()) {
            Node childCopy = (child instanceof File f)
                ? cloneFile(f, child.getName(), copy)
                : cloneDir((Directory) child, child.getName(), copy);
            copy.addChild(childCopy);
        }
        return copy;
    }
}
